  1108→// ErrBranchNotFound is returned by DeleteBranchCLI when the branch does not exist.
  1109→var ErrBranchNotFound = errors.New("branch not found")
  1110→
  1111→// DeleteBranchCLI deletes a git branch using the git CLI.
  1112→// Uses `git branch -D` instead of go-git's RemoveReference because go-git v5
  1113→// doesn't properly persist deletions when refs are packed (.git/packed-refs)
  1114→// or in a worktree context. This is the same class of go-git v5 bug that
  1115→// affects checkout and reset --hard (see HardResetWithProtection).
  1116→//
  1117→// Returns ErrBranchNotFound if the branch does not exist, allowing callers
  1118→// to use errors.Is for idempotent deletion patterns.
  1119→func DeleteBranchCLI(branchName string) error {
  1120→	ctx := context.Background()
  1121→
  1122→	// Pre-check: verify the branch exists so callers get a structured error
  1123→	// instead of parsing git's output string (which varies across locales).
  1124→	// git show-ref exits 1 for "not found" and 128+ for fatal errors (corrupt
  1125→	// repo, permissions, not a git directory). Only map exit code 1 to
  1126→	// ErrBranchNotFound; propagate other failures as-is.
  1127→	check := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+branchName) //nolint:gosec // branchName comes from internal shadow branch naming
  1128→	if err := check.Run(); err != nil {
  1129→		var exitErr *exec.ExitError
  1130→		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
  1131→			return fmt.Errorf("%w: %s", ErrBranchNotFound, branchName)
  1132→		}
  1133→		return fmt.Errorf("failed to check branch %s: %w", branchName, err)
  1134→	}
  1135→
  1136→	cmd := exec.CommandContext(ctx, "git", "branch", "-D", "--", branchName)
  1137→	if output, err := cmd.CombinedOutput(); err != nil {
  1138→		return fmt.Errorf("failed to delete branch %s: %s: %w", branchName, strings.TrimSpace(string(output)), err)
  1139→	}
  1140→	return nil
  1141→}
