  1147→	cmd := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+branchName) //nolint:gosec // branchName comes from internal shadow branch naming
  1148→	if err := cmd.Run(); err != nil {
  1149→		return fmt.Errorf("branch %s not found: %w", branchName, err)
  1150→	}
  1151→	return nil
  1152→}
