  1154→// HardResetWithProtection performs a git reset --hard to the specified commit.
  1155→// Uses the git CLI instead of go-git because go-git's HardReset incorrectly
  1156→// deletes untracked directories (like .entire/) even when they're in .gitignore.
  1157→// Returns the short commit ID (7 chars) on success for display purposes.
  1158→func HardResetWithProtection(commitHash plumbing.Hash) (shortID string, err error) {
  1159→	ctx := context.Background()
  1160→	hashStr := commitHash.String()
  1161→	cmd := exec.CommandContext(ctx, "git", "reset", "--hard", hashStr) //nolint:gosec // hashStr is a plumbing.Hash, not user input
  1162→	if output, err := cmd.CombinedOutput(); err != nil {
  1163→		return "", fmt.Errorf("reset failed: %s: %w", strings.TrimSpace(string(output)), err)
  1164→	}
  1165→
  1166→	// Return short commit ID for display
  1167→	shortID = hashStr
  1168→	if len(shortID) > 7 {
  1169→		shortID = shortID[:7]
  1170→	}
  1171→	return shortID, nil
  1172→}
