  1174→// collectUntrackedFiles collects all untracked files in the working directory.
  1175→// This is used to capture the initial state when starting a session,
  1176→// ensuring untracked files present at session start are preserved during rewind.
  1177→// Excludes .git/, .entire/, and .claude/ directories (which are system/config directories).
  1178→// Works correctly from any subdirectory within the repository.
  1179→func collectUntrackedFiles() ([]string, error) {
  1180→	// Get repository root to walk from there
  1181→	repoRoot, err := GetWorktreePath()
  1182→	if err != nil {
  1183→		repoRoot = "." // Fallback to current directory
  1184→	}
  1185→
  1186→	var untrackedFiles []string
  1187→	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
  1188→		if walkErr != nil {
  1189→			return nil //nolint:nilerr // Skip filesystem errors during walk
  1190→		}
  1191→
  1192→		// Get path relative to repo root
  1193→		relPath, err := filepath.Rel(repoRoot, path)
  1194→		if err != nil {
  1195→			return nil //nolint:nilerr // Skip paths we can't make relative
  1196→		}
  1197→
  1198→		// Skip directories
  1199→		if info.IsDir() {
  1200→			// Skip .git, .claude, and .entire directories
  1201→			if relPath == gitDir || relPath == claudeDir || relPath == entireDir ||
  1202→				strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, claudeDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
  1203→				return filepath.SkipDir
  1204→			}
  1205→			return nil
  1206→		}
  1207→
  1208→		// Skip files in special directories (shouldn't reach here due to SkipDir, but safety check)
  1209→		if strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, claudeDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
  1210→			return nil
  1211→		}
  1212→
  1213→		untrackedFiles = append(untrackedFiles, relPath)
  1214→		return nil
  1215→	})
  1216→	if err != nil {
  1217→		return nil, fmt.Errorf("failed to walk directory: %w", err)
  1218→	}
  1219→
  1220→	return untrackedFiles, nil
  1221→}
