  1223→// ExtractSessionIDFromCommit extracts the session ID from a commit's trailers.
  1224→// It checks the Entire-Session trailer first, then falls back to extracting from
  1225→// the metadata directory path in the Entire-Metadata trailer.
  1226→// Returns empty string if no session ID is found.
  1227→func ExtractSessionIDFromCommit(commit *object.Commit) string {
  1228→	// Try Entire-Session trailer first
  1229→	if sessionID, found := trailers.ParseSession(commit.Message); found {
  1230→		return sessionID
  1231→	}
  1232→
  1233→	// Try extracting from metadata directory (last path component)
  1234→	if metadataDir, found := trailers.ParseMetadata(commit.Message); found {
  1235→		return filepath.Base(metadataDir)
  1236→	}
  1237→
  1238→	return ""
  1239→}
