  1242→// - FlattenTree -> checkpoint.FlattenTree
  1243→// - CreateBlobFromContent -> checkpoint.CreateBlobFromContent
  1244→// - BuildTreeFromEntries -> checkpoint.BuildTreeFromEntries
  1245→// - sortTreeEntries (internal to checkpoint package)
