  1247→//
  1248→// See push_common.go and session_test.go for usage examples.
  1249→
  1250→// createCommit creates a commit object
  1251→func createCommit(repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
  1252→	now := time.Now()
  1253→	sig := object.Signature{
  1254→		Name:  authorName,
  1255→		Email: authorEmail,
  1256→		When:  now,
  1257→	}
  1258→
  1259→	commit := &object.Commit{
  1260→		TreeHash:  treeHash,
  1261→		Author:    sig,
  1262→		Committer: sig,
  1263→		Message:   message,
  1264→	}
  1265→
  1266→	// Add parent if not a new branch
  1267→	if parentHash != plumbing.ZeroHash {
  1268→		commit.ParentHashes = []plumbing.Hash{parentHash}
  1269→	}
  1270→
  1271→	obj := repo.Storer.NewEncodedObject()
  1272→	if err := commit.Encode(obj); err != nil {
  1273→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
  1274→	}
  1275→
  1276→	hash, err := repo.Storer.SetEncodedObject(obj)
  1277→	if err != nil {
  1278→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
  1279→	}
  1280→
  1281→	return hash, nil
  1282→}
