  1284→// getSessionDescriptionFromTree reads the first line of prompt.txt or context.md from a git tree.
  1285→// This is the tree-based equivalent of getSessionDescription (which reads from filesystem).
  1286→//
  1287→// If metadataDir is provided, looks for files at metadataDir/prompt.txt or metadataDir/context.md.
  1288→// If metadataDir is empty, first tries the root of the tree (for when the tree is already
  1289→// the session directory, e.g., auto-commit strategy's sharded metadata), then falls back to
  1290→// searching for .entire/metadata/*/prompt.txt or context.md (for full worktree trees).
  1291→func getSessionDescriptionFromTree(tree *object.Tree, metadataDir string) string {
  1292→	// Helper to read first line from a file in tree
  1293→	readFirstLine := func(path string) string {
  1294→		file, err := tree.File(path)
  1295→		if err != nil {
  1296→			return ""
  1297→		}
  1298→		content, err := file.Contents()
  1299→		if err != nil {
  1300→			return ""
  1301→		}
  1302→		lines := strings.SplitN(content, "\n", 2)
  1303→		if len(lines) > 0 && lines[0] != "" {
  1304→			desc := strings.TrimSpace(lines[0])
  1305→			// Remove markdown header prefix if present
  1306→			return strings.TrimPrefix(desc, "# ")
  1307→		}
  1308→		return ""
  1309→	}
  1310→
  1311→	// If metadataDir is provided, look there directly
  1312→	if metadataDir != "" {
  1313→		if desc := readFirstLine(metadataDir + "/" + paths.PromptFileName); desc != "" {
  1314→			return desc
  1315→		}
  1316→		if desc := readFirstLine(metadataDir + "/" + paths.ContextFileName); desc != "" {
  1317→			return desc
  1318→		}
  1319→		return NoDescription
  1320→	}
  1321→
  1322→	// No metadataDir provided - first try looking at the root of the tree
  1323→	// (used when the tree is already the session directory)
  1324→	if desc := readFirstLine(paths.PromptFileName); desc != "" {
  1325→		return desc
  1326→	}
  1327→	if desc := readFirstLine(paths.ContextFileName); desc != "" {
  1328→		return desc
  1329→	}
  1330→
  1331→	// Fall back to searching for .entire/metadata/*/prompt.txt or context.md
  1332→	// (used when the tree is the full worktree)
  1333→	var desc string
  1334→	//nolint:errcheck // We ignore errors here as we're just searching for a description
  1335→	_ = tree.Files().ForEach(func(f *object.File) error {
  1336→		if desc != "" {
  1337→			return nil // Already found description
  1338→		}
  1339→		name := f.Name
  1340→		if strings.Contains(name, ".entire/metadata/") {
  1341→			if strings.HasSuffix(name, "/"+paths.PromptFileName) || strings.HasSuffix(name, "/"+paths.ContextFileName) {
  1342→				content, err := f.Contents()
  1343→				if err != nil {
  1344→					return nil //nolint:nilerr // Skip files we can't read, continue searching
  1345→				}
  1346→				lines := strings.SplitN(content, "\n", 2)
  1347→				if len(lines) > 0 && lines[0] != "" {
  1348→					desc = strings.TrimSpace(lines[0])
  1349→					desc = strings.TrimPrefix(desc, "# ")
  1350→				}
  1351→			}
  1352→		}
  1353→		return nil
  1354→	})
  1355→
  1356→	if desc != "" {
  1357→		return desc
  1358→	}
  1359→	return NoDescription
  1360→}
