  1362→// GetGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
  1363→// It checks local config first, then falls back to global config.
  1364→// Returns ("Unknown", "unknown@local") if no user is configured - this allows
  1365→// operations to proceed even without git user config, which is especially useful
  1366→// for internal metadata commits on branches like entire/checkpoints/v1.
  1367→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
  1368→	// Get repository config (includes local settings)
  1369→	cfg, err := repo.Config()
  1370→	if err == nil {
  1371→		name = cfg.User.Name
  1372→		email = cfg.User.Email
  1373→	}
  1374→
  1375→	// If not found in local config, try global config
  1376→	if name == "" || email == "" {
  1377→		globalCfg, err := config.LoadConfig(config.GlobalScope)
  1378→		if err == nil {
  1379→			if name == "" {
  1380→				name = globalCfg.User.Name
  1381→			}
  1382→			if email == "" {
  1383→				email = globalCfg.User.Email
  1384→			}
  1385→		}
  1386→	}
  1387→
  1388→	// Provide sensible defaults if git user is not configured
  1389→	if name == "" {
  1390→		name = "Unknown"
  1391→	}
  1392→	if email == "" {
  1393→		email = "unknown@local"
  1394→	}
  1395→
  1396→	return name, email
  1397→}
