  1399→// GetCurrentBranchName returns the short name of the current branch if HEAD points to a branch.
  1400→// Returns an empty string if in detached HEAD state or if there's an error reading HEAD.
  1401→// This is used to capture branch metadata for checkpoints.
  1402→func GetCurrentBranchName(repo *git.Repository) string {
  1403→	head, err := repo.Head()
  1404→	if err != nil || !head.Name().IsBranch() {
  1405→		return ""
  1406→	}
  1407→	return head.Name().Short()
  1408→}
  1409→
  1410→// getMainBranchHash returns the hash of the main branch (main or master).
  1411→// Returns ZeroHash if no main branch is found.
  1412→func GetMainBranchHash(repo *git.Repository) plumbing.Hash {
  1413→	// Try common main branch names
  1414→	for _, branchName := range []string{branchMain, branchMaster} {
  1415→		// Try local branch first
  1416→		ref, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
  1417→		if err == nil {
  1418→			return ref.Hash()
  1419→		}
  1420→		// Try remote tracking branch
  1421→		ref, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
  1422→		if err == nil {
  1423→			return ref.Hash()
  1424→		}
  1425→	}
  1426→	return plumbing.ZeroHash
  1427→}
  1428→
  1429→// GetDefaultBranchName returns the name of the default branch.
  1430→// First checks origin/HEAD, then falls back to checking if main/master exists.
  1431→// Returns empty string if unable to determine.
  1432→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
  1433→func GetDefaultBranchName(repo *git.Repository) string {
  1434→	// Try to get the symbolic reference for origin/HEAD
  1435→	// Use resolved=false to get the symbolic ref itself, then extract its target
  1436→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), false)
  1437→	if err == nil && ref != nil && ref.Type() == plumbing.SymbolicReference {
  1438→		target := ref.Target().String()
  1439→		if branchName, found := strings.CutPrefix(target, "refs/remotes/origin/"); found {
  1440→			return branchName
  1441→		}
  1442→	}
  1443→
  1444→	// Fallback: check if origin/main or origin/master exists
  1445→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMain), true); err == nil {
  1446→		return branchMain
  1447→	}
  1448→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMaster), true); err == nil {
  1449→		return branchMaster
  1450→	}
  1451→
  1452→	// Final fallback: check local branches
  1453→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMain), true); err == nil {
  1454→		return branchMain
  1455→	}
  1456→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMaster), true); err == nil {
  1457→		return branchMaster
  1458→	}
  1459→
  1460→	return ""
  1461→}
  1462→
  1463→// IsOnDefaultBranch checks if the repository HEAD is on the default branch.
  1464→// Returns (isOnDefault, currentBranchName).
  1465→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
  1466→func IsOnDefaultBranch(repo *git.Repository) (bool, string) {
  1467→	currentBranch := GetCurrentBranchName(repo)
  1468→	if currentBranch == "" {
  1469→		return false, ""
  1470→	}
  1471→
  1472→	defaultBranch := GetDefaultBranchName(repo)
  1473→	if defaultBranch == "" {
  1474→		// Can't determine default, check common names
  1475→		if currentBranch == branchMain || currentBranch == branchMaster {
  1476→			return true, currentBranch
  1477→		}
  1478→		return false, currentBranch
  1479→	}
  1480→
  1481→	return currentBranch == defaultBranch, currentBranch
  1482→}
