   195→// GetAdditionalSessions implements SessionSource interface.
   196→// Returns active sessions from .git/entire-sessions/ that haven't yet been condensed.
   197→func (s *ManualCommitStrategy) GetAdditionalSessions() ([]*Session, error) {
   198→	activeStates, err := s.listAllSessionStates()
   199→	if err != nil {
   200→		return nil, fmt.Errorf("failed to list session states: %w", err)
   201→	}
   202→
   203→	if len(activeStates) == 0 {
   204→		return nil, nil
   205→	}
   206→
   207→	var sessions []*Session
   208→	for _, state := range activeStates {
   209→		session := &Session{
   210→			ID:          state.SessionID,
   211→			Description: NoDescription,
   212→			Strategy:    StrategyNameManualCommit,
   213→			StartTime:   state.StartedAt,
   214→		}
   215→
   216→		// Try to get description from shadow branch
   217→		if description := s.getDescriptionFromShadowBranch(state.SessionID, state.BaseCommit, state.WorktreeID); description != "" {
   218→			session.Description = description
   219→		}
   220→
   221→		sessions = append(sessions, session)
   222→	}
   223→
   224→	return sessions, nil
   225→}
