   448→// handleGeminiAfterAgent handles the AfterAgent hook for Gemini CLI.
   449→// This fires after the agent has finished processing and generated a response.
   450→// This is equivalent to Claude Code's "Stop" hook - it commits the session changes with metadata.
   451→// AfterAgent fires after EVERY user prompt/response cycle, making it the correct place
   452→// for checkpoint creation (not SessionEnd, which only fires on explicit exit).
   453→func handleGeminiAfterAgent() error {
   454→	// Always use Gemini agent for Gemini hooks
   455→	ag, err := agent.Get("gemini")
   456→	if err != nil {
   457→		return fmt.Errorf("failed to get gemini agent: %w", err)
   458→	}
   459→
   460→	// Parse hook input using HookStop - AfterAgent provides the same data as Stop
   461→	// (session_id, transcript_path) which is what we need for committing
   462→	input, err := ag.ParseHookInput(agent.HookStop, os.Stdin)
   463→	if err != nil {
   464→		return fmt.Errorf("failed to parse hook input: %w", err)
   465→	}
   466→
   467→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
   468→	logging.Info(logCtx, "gemini-after-agent",
   469→		slog.String("hook", "after-agent"),
   470→		slog.String("hook_type", "agent"),
   471→		slog.String("model_session_id", input.SessionID),
   472→		slog.String("transcript_path", input.SessionRef),
   473→	)
   474→
   475→	sessionID := input.SessionID
   476→	if sessionID == "" {
   477→		sessionID = unknownSessionID
   478→	}
   479→
   480→	transcriptPath := input.SessionRef
   481→	if transcriptPath == "" || !fileExists(transcriptPath) {
   482→		return fmt.Errorf("transcript file not found or empty: %s", transcriptPath)
   483→	}
   484→
   485→	// Create session context and commit
   486→	ctx := &geminiSessionContext{
   487→		sessionID:      sessionID,
   488→		transcriptPath: transcriptPath,
   489→	}
   490→
   491→	if err := setupGeminiSessionDir(ctx); err != nil {
   492→		return err
   493→	}
   494→
   495→	if err := extractGeminiMetadata(ctx); err != nil {
   496→		return err
   497→	}
   498→
   499→	if err := commitGeminiSession(ctx); err != nil {
   500→		return err
   501→	}
   502→
   503→	// Transition session ACTIVE → IDLE (equivalent to Claude's transitionSessionTurnEnd)
   504→	transitionSessionTurnEnd(sessionID)
   505→
   506→	return nil
   507→}
