   235→// ensureMetadataBranch creates the orphan entire/checkpoints/v1 branch if it doesn't exist.
   236→// This branch has no parent and starts with an empty tree.
   237→func EnsureMetadataBranch(repo *git.Repository) error {
   238→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   239→
   240→	// Check if branch already exists
   241→	_, err := repo.Reference(refName, true)
   242→	if err == nil {
   243→		// Branch already exists
   244→		return nil
   245→	}
   246→
   247→	// Create empty tree (no files)
   248→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
   249→	obj := repo.Storer.NewEncodedObject()
   250→	if err := emptyTree.Encode(obj); err != nil {
   251→		return fmt.Errorf("failed to encode empty tree: %w", err)
   252→	}
   253→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
   254→	if err != nil {
   255→		return fmt.Errorf("failed to store empty tree: %w", err)
   256→	}
   257→
   258→	// Create orphan commit (no parent)
   259→	now := time.Now()
   260→	sig := object.Signature{
   261→		Name:  "Entire",
   262→		Email: "entire@local",
   263→		When:  now,
   264→	}
   265→
   266→	commit := &object.Commit{
   267→		TreeHash:  emptyTreeHash,
   268→		Author:    sig,
   269→		Committer: sig,
   270→		Message:   "Initialize metadata branch\n\nThis branch stores session metadata for the auto-commit strategy.\n",
   271→	}
   272→	// Note: No ParentHashes - this is an orphan commit
   273→
   274→	commitObj := repo.Storer.NewEncodedObject()
   275→	if err := commit.Encode(commitObj); err != nil {
   276→		return fmt.Errorf("failed to encode orphan commit: %w", err)
   277→	}
   278→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
   279→	if err != nil {
   280→		return fmt.Errorf("failed to store orphan commit: %w", err)
   281→	}
   282→
   283→	// Create branch reference
   284→	ref := plumbing.NewHashReference(refName, commitHash)
   285→	if err := repo.Storer.SetReference(ref); err != nil {
   286→		return fmt.Errorf("failed to create metadata branch: %w", err)
   287→	}
   288→
   289→	fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
   290→	return nil
   291→}
