   330→							var sessionMetadata checkpoint.CommittedMetadata
   331→							if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   332→								sessionIDs = append(sessionIDs, sessionMetadata.SessionID)
   333→								// Use first session for Agent, SessionID, CreatedAt, IsTask, ToolUseID
   334→								if i == 0 {
   335→									info.Agent = sessionMetadata.Agent
   336→									info.SessionID = sessionMetadata.SessionID
   337→									info.CreatedAt = sessionMetadata.CreatedAt
   338→									info.IsTask = sessionMetadata.IsTask
   339→									info.ToolUseID = sessionMetadata.ToolUseID
