   179→// GetSessionDir returns the directory where Gemini stores session transcripts.
   180→// Gemini stores sessions in ~/.gemini/tmp/<project-hash>/chats/
   181→func (g *GeminiCLIAgent) GetSessionDir(repoPath string) (string, error) {
   182→	// Check for test environment override
   183→	if override := os.Getenv("ENTIRE_TEST_GEMINI_PROJECT_DIR"); override != "" {
