   197→// ReadSession reads a session from Gemini's storage (JSON transcript file).
   198→// The session data is stored in NativeData as raw JSON bytes.
   199→func (g *GeminiCLIAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
   200→	if input.SessionRef == "" {
   201→		return nil, errors.New("session reference (transcript path) is required")
   202→	}
   203→
   204→	// Read the raw JSON file
   205→	data, err := os.ReadFile(input.SessionRef)
   206→	if err != nil {
   207→		return nil, fmt.Errorf("failed to read transcript: %w", err)
   208→	}
