   260→// SanitizePathForGemini converts a path to Gemini's project directory format.
   261→// Gemini uses a hash-like sanitization similar to Claude.
   262→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
   263→
   264→func SanitizePathForGemini(path string) string {
