	fmt.Fprintf(w, "Auto-commit strategy: %v\n", isAutoCommit)

	_, branchName, err := IsOnDefaultBranch()
	if err != nil {
		fmt.Fprintf(w, "Branch: (unable to determine: %v)\n\n", err)
	} else {
